from produire import produire
from format_lecon import paras,table,steps
from medicaments import nasonex
parts=[
('La {rhinite allergique est une inflammation nasale liée à un allergène}. Prurit, éternuements, rhinorrhée et obstruction sont typiques. Elle peut favoriser le ronflement sans expliquer toutes les apnées.',paras('La maladie repose sur une réponse immunitaire médiée par les IgE. Une sensibilisation biologique isolée n’est pas suffisante : l’exposition doit correspondre à une histoire symptomatique compatible.', 'La congestion augmente la résistance nasale et favorise la respiration buccale. Une amélioration sous traitement nasal ne permet pas, à elle seule, d’exclure un trouble respiratoire du sommeil.')),
('Le {contexte est souvent atopique et lié aux expositions}. Pollens, acariens et animaux sont des déclencheurs courants. La durée et le retentissement comptent davantage qu’une simple opposition saisonnier ou permanent.',paras('Les HUG décrivent une maladie très fréquente en Suisse et insistent sur son association avec l’asthme. Rechercher toux, sifflements et dyspnée plutôt que limiter la consultation au nez.', 'L’allergie peut persister ou apparaître à l’âge adulte. Un symptôme nocturne fréquent peut dépendre d’une exposition dans la chambre, mais cette hypothèse ne remplace pas l’interrogatoire sur les apnées.')),
('La {réaction allergique associe phase immédiate et inflammation prolongée}. Des médiateurs libérés après exposition provoquent prurit et éternuements. L’œdème entretient ensuite la congestion.',paras('L’activation des mastocytes et basophiles implique l’histamine et d’autres médiateurs. La phase tardive peut prolonger l’obstruction après l’exposition initiale.', 'Le sommeil peut être perturbé par la gêne nasale, tandis qu’une sédation médicamenteuse peut ajouter une somnolence. Ces mécanismes ne sont pas équivalents à une apnée obstructive documentée.')),
('Les {alarmes imposent de sortir du diagnostic allergique simple}. Une détresse respiratoire ou un asthme sévère nécessite une prise en charge urgente. Unilatéralité persistante ou saignement impose un bilan ORL.',paras('Une obstruction avec signes orbitaires, fièvre importante ou douleur inhabituelle peut relever d’une infection ou d’une complication. Une masse ou des symptômes neurologiques ne doivent pas être traités indéfiniment comme une allergie.', 'Des pauses nocturnes et une somnolence au volant demandent une exploration du sommeil et une réduction immédiate du risque. Ne pas attendre que le traitement nasal ait fini d’agir.')),
('L’{anamnèse cherche une concordance avec l’exposition}. Préciser calendrier, lieux, animaux, travail et symptômes oculaires. Évaluer sommeil, activités et traitements utilisés.',paras('Demander fréquence et durée, gêne lors des loisirs ou au travail, antécédents d’asthme et d’eczéma. Une exposition professionnelle peut justifier une démarche spécifique.', 'Vérifier les sprays vasoconstricteurs répétés, médicaments sédatifs, technique d’application et observance. Une mauvaise utilisation du spray peut expliquer un échec apparent.')),
('L’{examen apprécie nez, yeux et voies respiratoires inférieures}. Une rhinoscopie examine cornets et sécrétions. L’auscultation recherche un asthme associé.',paras('Les HUG recommandent également examen de l’oropharynx et recherche de signes cutanés d’atopie. L’aspect muqueux est un argument, pas une preuve étiologique isolée.', 'Rechercher polypes, déviation de cloison ou anomalie unilatérale. Les symptômes récurrents mal contrôlés justifient un avis ORL pour vérifier une cause structurelle.')),
('L’{approche syndromique distingue allergie et autres rhinites}. Une congestion peut être médicamenteuse, irritative ou hormonale. Elle peut aussi résulter d’un obstacle anatomique.',table(['Association','Hypothèse'],[['Prurit, éternuements, exposition concordante.','Rhinite allergique.'],['Usage prolongé de spray vasoconstricteur.','Rhinite médicamenteuse.'],['Anosmie et obstruction chronique bilatérale.','Polypose possible.'],['Obstruction progressive d’un seul côté, sang.','Lésion structurelle ou tumorale à rechercher.'] ])),
('Le {diagnostic est souvent clinique lorsque l’histoire est claire}. Les tests précisent une sensibilisation utile à la décision. Ils doivent toujours être confrontés aux symptômes.',paras('Les tests cutanés ou IgE spécifiques peuvent aider si doute diagnostique ou projet d’immunothérapie. Un résultat positif sans manifestations à l’exposition n’établit pas une allergie causale.', 'Les HUG ne recommandent pas le dosage des IgE totales comme test diagnostique spécifique. Une rhinite allergique locale peut exister malgré des tests systémiques négatifs ; son exploration est spécialisée.')),
('Les {examens complémentaires restent ciblés}. La spirométrie est indiquée si un asthme est suspecté. L’imagerie n’est pas un examen systématique d’une rhinite typique.',paras('L’allergologue choisit les tests selon l’histoire et les médicaments susceptibles d’en modifier les résultats. La recherche indifférenciée de nombreux allergènes peut produire des résultats difficiles à interpréter.', 'Une suspicion d’apnées demande sa propre exploration. Un test allergologique ne renseigne ni sur les pauses respiratoires ni sur l’oxygénation nocturne.')),
('L’{algorithme combine diagnostic, technique et réévaluation}. Traiter les alarmes puis identifier les expositions pertinentes. Une réponse insuffisante conduit à vérifier la cause avant d’accumuler des produits.',steps('Rechercher urgence respiratoire, unilatéralité et signes d’apnées.', 'Établir l’histoire allergique et évaluer un asthme associé.', 'Réduire les expositions accessibles et expliquer le traitement local.', 'Vérifier technique, régularité, tolérance et bénéfice.', 'Si contrôle insuffisant, avis allergologique ou ORL ; discuter immunothérapie si indiquée.')),
('La {prise en charge suisse utilise un traitement nasal adapté}. Les corticostéroïdes intranasaux sont une option de première ligne. Leur indication, leur âge d’emploi et leur dose suivent la spécialité.',paras('Les HUG préconisent les corticostéroïdes intranasaux et, selon le retentissement, une association avec un antihistaminique nasal. L’exemple chiffré ci-dessous est limité à Nasonex et provient de sa notice suisse, sans transposition d’une autre molécule.', '@@MEDICAMENTS@@', 'Éviction ciblée et soins nasaux accompagnent le traitement. Les antihistaminiques sédatifs peuvent gêner la vigilance ; éviter de les choisir comme aide au sommeil. Une immunothérapie se discute si les symptômes restent importants malgré un traitement bien conduit.')),
('La {prévention repose sur l’exposition et la bonne utilisation}. Expliquer l’effet différé et la régularité du spray. Surveiller irritation, épistaxis et évolution respiratoire.',paras('Diriger le jet vers la paroi latérale, loin de la cloison, tête légèrement inclinée en avant, sans inspiration forcée. Une démonstration permet de corriger les erreurs.', 'En cas de traitement prolongé chez l’enfant, surveiller croissance et muqueuse. Si le nez s’améliore mais que fatigue et pauses persistent, poursuivre le bilan du sommeil.')),
('Le {point clé est une attribution causale prudente}. Une allergie peut expliquer le nez bouché et contribuer au bruit. Elle n’exclut pas une obstruction pharyngée nocturne.',paras('Traiter la maladie démontrée, vérifier la technique et surveiller le résultat. Une posologie de polypose ne doit pas être appliquée par défaut à une rhinite, ni inversement.'))]
quiz=[('Une sensibilisation positive prouve-t-elle l’allergie symptomatique ?','Non, il faut une histoire compatible.'),('Quel symptôme est évocateur avec les éternuements ?','Le prurit nasal ou oculaire.'),('Faut-il rechercher un asthme ?','Oui.'),('Les IgE totales sont-elles un test spécifique suffisant ?','Non.'),('Une unilatéralité persistante doit-elle faire revoir le diagnostic ?','Oui.'),('Une rhinite peut-elle coexister avec des apnées ?','Oui.'),('Le spray doit-il viser la cloison ?','Non, viser la paroi latérale.'),('Nasonex agit-il comme un décongestionnant immédiat ?','Non, son effet est différé.'),('Quel âge minimal figure pour la rhinite dans la notice suisse citée ?','Six ans.'),('Peut-on augmenter la dose citée chez l’enfant de six à onze ans ?','Non, la notice l’interdit.'),('Le traitement nasal guérit-il nécessairement les apnées ?','Non.'),('Une somnolence sous antihistaminique est-elle anodine pour la conduite ?','Non.'),('La grossesse autorise-t-elle sans condition le spray cité ?','Non, la notice limite son usage à une nécessité absolue.'),('Un échec apparent peut-il venir de la technique ?','Oui.')]
produire(4,parts,quiz,(1,4,9,18),nasonex)
